"""The YAML schemas must use only the vocabulary in src/aliprocessing/schemas/README.md."""

from __future__ import annotations

import copy

import pytest

from aliprocessing.schemas import PRODUCTS, load_schema

TOP_LEVEL_KEYS = {
    "product",
    "schema_version",
    "status",
    "description",
    "dimensions",
    "variables",
    "attributes",
    "model",
    "groups",
    "file",
    "constraints",
    "open_questions",
}
FIELD_KEYS = {
    "dims",
    "dtype",
    "units",
    "required",
    "required_when",
    "default",
    "valid_min",
    "valid_max",
    "allowed",
    "role",
    "description",
    "open_questions",
}
DTYPES = {"float", "int", "bool", "datetime", "str"}
ROLES = {
    "measurement",
    "geometry",
    "acquisition",
    "instrument",
    "quality",
    "processing",
    "simulator_truth",
}


def schema_problems(schema: dict) -> list[str]:
    problems = [
        f"unknown top-level key {key!r}" for key in set(schema) - TOP_LEVEL_KEYS
    ]
    dimensions = set(schema.get("dimensions", {}))
    question_ids = {question["id"] for question in schema.get("open_questions", [])}

    def check_fields(fields: dict, where: str, is_attribute: bool) -> None:
        for name, field in fields.items():
            location = f"{where}.{name}"
            problems.extend(
                f"{location}: unknown key {key!r}" for key in set(field) - FIELD_KEYS
            )
            if field.get("dtype") not in DTYPES:
                problems.append(f"{location}: dtype {field.get('dtype')!r}")
            if field.get("role") not in ROLES:
                problems.append(f"{location}: role {field.get('role')!r}")
            if not field.get("description"):
                problems.append(f"{location}: missing description")
            if not is_attribute:
                if "dims" not in field:
                    problems.append(f"{location}: missing dims")
                problems.extend(
                    f"{location}: undeclared dimension {dim!r}"
                    for dim in field.get("dims", [])
                    if dim not in dimensions
                )
            for condition in field.get("required_when", {}):
                if condition not in fields and condition not in schema.get(
                    "variables", {}
                ):
                    problems.append(
                        f"{location}: required_when on unknown {condition!r}"
                    )
            problems.extend(
                f"{location}: unknown open question {ref!r}"
                for ref in field.get("open_questions", [])
                if ref not in question_ids
            )

    check_fields(schema.get("variables", {}), "variables", is_attribute=False)
    check_fields(schema.get("attributes", {}), "attributes", is_attribute=True)
    for name, group in schema.get("groups", {}).items():
        check_fields(group["variables"], f"groups.{name}.variables", is_attribute=False)

    problems.extend(
        f"dimensions.{dim}: coordinate has no variable"
        for dim, spec in schema.get("dimensions", {}).items()
        if spec.get("coordinate") and dim not in schema.get("variables", {})
    )
    return problems


@pytest.mark.parametrize("product", PRODUCTS)
def test_schema_is_well_formed(product):
    assert schema_problems(load_schema(product)) == []


def test_problems_are_detected():
    schema = copy.deepcopy(load_schema("l1a"))
    image = schema["variables"]["image"]
    image["dims"] = ["time", "row"]
    image["dtype"] = "double"
    image["unit"] = "count"

    problems = schema_problems(schema)

    assert len(problems) == 3
    assert all(problem.startswith("variables.image:") for problem in problems)


def test_coordinate_without_variable_is_detected():
    schema = copy.deepcopy(load_schema("l1b"))
    del schema["variables"]["altitude"]
    assert schema_problems(schema) == [
        "dimensions.altitude: coordinate has no variable"
    ]
